#include <bits/stdc++.h>
using namespace std;

struct FlowSolver {
    struct Edge {
        int from, to;
        long long flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> adj[7100];
    int level[7100], current[7100];

    void clear() {
        edges.clear();
        for (int i = 0; i < 7100; ++i) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, long long cap) {
        edges.push_back({u, v, 0, cap});
        edges.push_back({v, u, 0, 0});
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildGraph() {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &idx : adj[u]) {
                auto &e = edges[idx];
                if (e.capacity > e.flow && level[e.to] < 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }

    long long sendFlow(int u, long long flow) {
        if (u == t || flow == 0) return flow;
        long long total = 0;
        for (int &i = current[u]; i < (int)adj[u].size(); ++i) {
            auto &e = edges[adj[u][i]];
            if (level[e.to] == level[u] + 1 && e.capacity > e.flow) {
                long long pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[u][i] ^ 1].flow -= pushed;
                    total += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return total;
    }

    long long maxFlow() {
        long long totalFlow = 0;
        while (buildGraph()) {
            for (int i = 0; i < 7100; ++i) current[i] = 0;
            totalFlow += sendFlow(s, LLONG_MAX);
        }
        return totalFlow;
    }
};

FlowSolver fs;
char mazeA[14][14], mazeB[14][14];
bool visitedCells[14][14];
int distMap[14][14];
int n;
int targetNodes[103];

void performBFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; ++i)
        for (int j = 0; j < 14; ++j)
            distMap[i][j] = 111;
    distMap[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visitedCells[cx][cy]) continue;
        visitedCells[cx][cy] = true;
        distMap[cx][cy] = d;
        for (int dir = 0; dir < 4; ++dir) {
            int nx = cx + dx[dir], ny = cy + dy[dir];
            if (nx <= 0 || nx > n || ny <= 0 || ny > n || visitedCells[nx][ny] || mazeA[nx][ny] == 'Y') continue;
            q.push({{nx, ny}, d + 1});
        }
    }
}

int getIdx(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    int t, i, j, k;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; ++i) scanf("%s", mazeA[i] + 1);
    for (i = 1; i <= n; ++i) scanf("%s", mazeB[i] + 1);
    fs.s = 0; fs.t = 7099;
    int startX = 0, startY = 0;
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (mazeA[i][j] == 'Z') {
                startX = i; startY = j; break;
            }
        }
    }
    for (i = 1; i <= n * n; ++i) targetNodes[i] = 7098 - (n * n - i);
    performBFS(startX, startY);
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= n; ++j) {
            if (mazeA[i][j] >= '0' && mazeA[i][j] <= '9')
                fs.addEdge(fs.s, getIdx(0, i, j), mazeA[i][j] - '0');
            if (mazeB[i][j] >= '0' && mazeB[i][j] <= '9')
                fs.addEdge(targetNodes[getIdx(0, i, j)], fs.t, mazeB[i][j] - '0');
            fs.addEdge(getIdx(0, i, j), targetNodes[getIdx(0, i, j)], LLONG_MAX);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; ++i) {
        for (j = 1; j <= n; ++j) {
            for (k = 1; k <= n; ++k) {
                if (mazeA[j][k] == 'Y' || mazeA[j][k] == 'Z') continue;
                for (int l = 0; l < 4; ++l) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && mazeA[tx][ty] != 'Y' && mazeA[tx][ty] != 'Z') {
                        if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                            fs.addEdge(getIdx(i - 1, tx, ty), getIdx(i, j, k), LLONG_MAX);
                        }
                    }
                }
                fs.addEdge(getIdx(i, j, k), targetNodes[getIdx(0, j, k)], LLONG_MAX);
            }
        }
    }
    printf("%lld\n", fs.maxFlow());
    return 0;
}
